import time


def retry(func, *, attempts=5, base_delay=0.5, max_delay=30.0, exceptions=(Exception,)):
    """Call func(), retrying on failure with exponential backoff and full jitter."""
    for attempt in range(attempts):
        try:
            return func()
        except exceptions:
            if attempt == attempts - 1:
                raise
            delay = min(max_delay, base_delay * 2 ** attempt)
            time.sleep(random.uniform(0, delay))
